-- Run in Supabase Dashboard > SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.projects(id uuid primary key default gen_random_uuid(),title text not null,category text not null default 'Full-stack',description text not null,technologies text[] not null default '{}',github_url text not null default '',live_url text not null default '',featured boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.contact_messages(id uuid primary key default gen_random_uuid(),name text not null,email text not null,message text not null,created_at timestamptz not null default now());
alter table public.projects enable row level security;alter table public.contact_messages enable row level security;
drop policy if exists "Anyone can view projects" on public.projects;create policy "Anyone can view projects" on public.projects for select using(true);
insert into public.projects(title,category,description,technologies,github_url,featured) select 'School Management System','Full-stack','A platform for student records, course management, enrollment and school administration.',array['Node.js','Express','MySQL','JavaScript'],'https://github.com/miguel-zayn',true where not exists(select 1 from public.projects where title='School Management System');
insert into public.projects(title,category,description,technologies,github_url,featured) select 'STUGRAM','Web application','A student-focused social platform concept connecting campus communities and conversations.',array['React','Node.js','Supabase'],'https://github.com/miguel-zayn',true where not exists(select 1 from public.projects where title='STUGRAM');
insert into public.projects(title,category,description,technologies,github_url,featured) select 'Movie Discovery Platform','Frontend','A movie browsing experience with searchable titles, details and trailer discovery.',array['React','JavaScript','CSS'],'https://github.com/miguel-zayn',true where not exists(select 1 from public.projects where title='Movie Discovery Platform');
